import limited_client as robot,numpy as np
o=robot.observe('corner4'); K=o['intrinsic'];T=o['camera_to_world']
for v in range(178,205,4):
 for u in range(214,241,4):
  d=float(o['depth_m'][v,u]); col=o['rgb'][v,u]; p=T[:3,:3]@(np.linalg.inv(K)@np.array([u,v,1.]))*d+T[:3,3]
  if col[0]>70 and col[1]>40 and col[2]>30 and col[0]<220: print((u,v),col.tolist(),round(d,3),np.round(p,3))
