import limited_client as robot,numpy as np
o=robot.observe('corner4'); rgb=o['rgb'];d=o['depth_m'];
for v in range(180,230):
 for u in range(210,260):
  r,g,b=map(int,rgb[v,u]);
  if max(r,g,b)-min(r,g,b)<12 and 65<r<180 and d[v,u]>0 and d[v,u]<1.2:
   T=o['camera_to_world'];p=T[:3,:3]@(np.linalg.inv(o['intrinsic'])@np.array([u,v,1.]))*d[v,u]+T[:3,3]
   if p[2]>.015: print(u,v,tuple(rgb[v,u]),np.round(p,3))
